pluginManagement {
    repositories {
        gradlePluginPortal()
        mavenLocal()
        maven("https://repo.papermc.io/repository/maven-public/")
    }
}

plugins {
    id("org.gradle.toolchains.foojay-resolver-convention") version "1.0.0"
}

rootProject.name = "multipaper"

include("multipaper-api")
include("multipaper-server")
include("paper-checkstyle")

// MultiPaper-Master and its messaging protocol module are checked into the
// repository directly (they are not generated by the paperweight patch tasks).
for (name in listOf("MultiPaper-MasterMessagingProtocol", "MultiPaper-Master")) {
    if (file(name).isDirectory) {
        val projName = name.lowercase(java.util.Locale.ENGLISH)
        include(projName)
        findProject(":$projName")!!.projectDir = file(name)
    }
}
